:root {
  --ink: #08130f;
  --ink-2: #0e211a;
  --panel: rgba(9, 24, 19, 0.78);
  --panel-line: rgba(159, 219, 172, 0.24);
  --cream: #f1ead9;
  --muted: #a8bda9;
  --green: #8be0a4;
  --green-deep: #3b8f5e;
  --gold: #ffd06a;
  --hp: #e75f54;
  --hp-2: #ff8a70;
  --mp: #4aa9ff;
  --mp-2: #83d3ff;
  --xp: #ffd166;
  --danger: #ff6b5b;
  --safe: #7fe08c;
  --font: "Trebuchet MS", "Gill Sans", "Segoe UI", system-ui, sans-serif;
  --font-display: "Copperplate", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--cream);
  font-family: var(--font);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { touch-action: none; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: radial-gradient(circle at 50% 35%, #21483a, #08130f 80%);
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.hidden { display: none !important; }

/* ---------- HUD ---------- */
.hud {
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  opacity: 0;
  transition: opacity .55s ease .15s;
}
body.started .hud { opacity: 1; }

.hud-top {
  position: absolute;
  top: calc(14px + var(--safe-top));
  left: calc(16px + var(--safe-left));
  right: calc(16px + var(--safe-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  pointer-events: none;
}

.panel {
  background:
    linear-gradient(135deg, rgba(255,255,255,.06), transparent 40%),
    var(--panel);
  border: 1px solid var(--panel-line);
  box-shadow: 0 10px 30px rgba(0,0,0,.32), inset 0 1px 0 rgba(255,255,255,.06);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
}

.player-panel {
  width: min(390px, 38vw);
  display: flex;
  gap: 11px;
  padding: 10px 14px 10px 10px;
}

.portrait {
  position: relative;
  flex: 0 0 auto;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 30%, #2c5d4b, #11271f 70%);
  border: 1px solid rgba(139,224,164,.4);
  box-shadow: inset 0 0 18px rgba(0,0,0,.5), 0 0 14px rgba(139,224,164,.08);
  display: grid;
  place-items: center;
}
.portrait svg { width: 52px; height: 52px; filter: drop-shadow(0 2px 3px rgba(0,0,0,.4)); }
.level-badge {
  position: absolute;
  right: -4px;
  bottom: -4px;
  min-width: 24px;
  height: 24px;
  padding: 0 5px;
  border-radius: 50%;
  background: linear-gradient(180deg, #f6d481, #c98c2e);
  color: #241708;
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 700;
  line-height: 24px;
  text-align: center;
  border: 2px solid #17281f;
  box-shadow: 0 2px 8px rgba(0,0,0,.4);
}

.player-stats { flex: 1; min-width: 0; }
.player-title-row { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; margin-bottom: 5px; }
.player-name { font-family: var(--font-display); font-size: 13px; letter-spacing: .16em; color: #f3eedf; }
.player-rank { font-size: 8px; letter-spacing: .14em; color: var(--gold); opacity: .85; white-space: nowrap; }

.bar {
  position: relative;
  display: flex;
  align-items: center;
  gap: 5px;
  height: 17px;
  margin-bottom: 4px;
  filter: drop-shadow(0 2px 3px rgba(0,0,0,.3));
}
.bar-icon { width: 13px; height: 13px; flex: 0 0 auto; }
.health .bar-icon { fill: var(--hp-2); }
.mana .bar-icon { fill: var(--mp-2); }
.bar-track {
  position: relative;
  flex: 1;
  height: 12px;
  background: rgba(0,0,0,.5);
  border: 1px solid rgba(0,0,0,.55);
  border-radius: 2px;
  overflow: hidden;
  box-shadow: inset 0 2px 5px rgba(0,0,0,.55);
}
.bar-fill {
  position: absolute;
  inset: 1px auto 1px 1px;
  width: 100%;
  border-radius: 1px;
  transition: width .18s ease-out;
}
.health .bar-fill { background: linear-gradient(180deg, var(--hp-2), var(--hp) 55%, #a9332e); }
.mana .bar-fill { background: linear-gradient(180deg, var(--mp-2), var(--mp) 55%, #226bb5); }
.bar-shine {
  position: absolute;
  inset: 1px;
  background: linear-gradient(180deg, rgba(255,255,255,.22), transparent 45%, rgba(0,0,0,.1));
  pointer-events: none;
}
.bar-text {
  flex: 0 0 auto;
  width: 65px;
  text-align: right;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .04em;
  color: #e9f2e5;
  text-shadow: 0 1px 2px #000;
  font-variant-numeric: tabular-nums;
}
.xp-row { display: flex; align-items: center; gap: 7px; margin-top: 3px; }
.xp-track {
  flex: 1;
  height: 4px;
  border-radius: 2px;
  background: rgba(0,0,0,.5);
  overflow: hidden;
}
.xp-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #e1a941, var(--xp));
  box-shadow: 0 0 7px rgba(255,209,102,.55);
  transition: width .25s ease-out;
}
.xp-text { font-size: 8px; color: #c9d9c5; letter-spacing: .06em; white-space: nowrap; }
.level-max { display: none; font-family: var(--font-display); font-size: 9px; letter-spacing: .12em; color: var(--gold); text-shadow: 0 0 8px rgba(255,209,102,.6); }
.xp-row.maxed .level-max { display: inline; }
.xp-row.maxed .xp-text { display: none; }
.xp-row.maxed .xp-fill { background: linear-gradient(90deg, #ffd166, #fff0b8, #ffd166); animation: shimmer 2s infinite linear; background-size: 200% 100%; }
@keyframes shimmer { to { background-position: 200% 0; } }

.zone-pill {
  position: absolute;
  left: 50%;
  top: 2px;
  transform: translateX(-50%);
  min-width: 206px;
  padding: 6px 18px 8px;
  text-align: center;
  background: linear-gradient(180deg, rgba(7,20,15,.82), rgba(7,20,15,.42));
  border: 1px solid rgba(139,224,164,.24);
  border-radius: 3px 3px 10px 10px;
  box-shadow: 0 5px 20px rgba(0,0,0,.3);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  clip-path: polygon(7% 0, 93% 0, 100% 100%, 0 100%);
}
.zone-label {
  display: block;
  font-family: var(--font-display);
  font-size: 12px;
  letter-spacing: .2em;
  color: var(--green);
  line-height: 1;
}
.zone-name { display: block; margin-top: 3px; font-size: 8px; letter-spacing: .2em; color: var(--muted); }
.zone-track { margin: 6px auto 4px; width: 82%; height: 3px; background: rgba(0,0,0,.5); border-radius: 2px; overflow: hidden; }
.zone-track i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--safe), var(--gold) 60%, var(--danger)); transition: width .4s ease; }
.zone-distance { font-size: 8px; letter-spacing: .08em; color: #96ad97; }

.score-panel {
  width: 176px;
  padding: 9px 14px 10px;
  text-align: right;
  clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px);
}
.score-label { font-family: var(--font-display); font-size: 9px; letter-spacing: .3em; color: var(--muted); }
.score-value {
  font-family: var(--font-display);
  font-size: 30px;
  line-height: 1.05;
  color: #fff8e6;
  text-shadow: 0 2px 12px rgba(255,209,102,.18);
  font-variant-numeric: tabular-nums;
  letter-spacing: .02em;
}
.best-row { margin-top: 3px; font-size: 8px; letter-spacing: .16em; color: #a9bea9; }
.best-row b { color: var(--gold); font-weight: 700; font-size: 10px; }
.multiplier {
  margin-top: 5px;
  display: inline-block;
  padding: 2px 7px;
  border: 1px solid rgba(255,209,102,.35);
  color: var(--gold);
  background: rgba(255,209,102,.08);
  font-size: 8px;
  letter-spacing: .1em;
  opacity: 0;
  transform: translateY(-3px);
  transition: opacity .2s, transform .2s;
}
.multiplier.on { opacity: 1; transform: none; }

.hud-side {
  position: absolute;
  left: calc(18px + var(--safe-left));
  bottom: calc(20px + var(--safe-bottom));
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: flex-start;
  pointer-events: none;
}
.radar-wrap {
  position: relative;
  width: 170px;
  height: 170px;
  filter: drop-shadow(0 8px 16px rgba(0,0,0,.35));
}
#radar {
  width: 170px;
  height: 170px;
  border-radius: 50%;
  display: block;
  background: rgba(7,18,13,.66);
  border: 1px solid rgba(139,224,164,.24);
  box-shadow: inset 0 0 30px rgba(0,0,0,.55), 0 0 0 4px rgba(7,18,13,.35);
}
.radar-caption {
  position: absolute;
  left: 50%;
  bottom: -3px;
  transform: translateX(-50%);
  font-size: 7px;
  letter-spacing: .2em;
  color: #8fa993;
  background: rgba(7,18,13,.8);
  padding: 2px 8px;
  border-radius: 2px;
}
.radar-north {
  position: absolute;
  top: 5px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-display);
  font-size: 9px;
  color: rgba(240,235,218,.55);
}

.combo-toast {
  font-family: var(--font-display);
  font-size: 20px;
  letter-spacing: .08em;
  color: var(--gold);
  text-shadow: 0 0 16px rgba(255,160,60,.6), 0 2px 4px #000;
  opacity: 0;
  transform: translateY(6px) scale(.94);
  transition: opacity .18s, transform .18s;
}
.combo-toast.on { opacity: 1; transform: none; }

.hint {
  position: absolute;
  left: 50%;
  bottom: calc(24px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 7px 16px;
  border-radius: 20px;
  background: rgba(7,18,13,.64);
  border: 1px solid rgba(159,219,172,.16);
  color: #c3d4c1;
  font-size: 10px;
  letter-spacing: .06em;
  white-space: nowrap;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition: opacity .6s;
}
.hint span { display: flex; align-items: center; gap: 5px; }
.hint kbd {
  display: inline-grid;
  place-items: center;
  min-width: 19px;
  height: 19px;
  padding: 0 4px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,.22);
  border-bottom-width: 2px;
  background: rgba(255,255,255,.07);
  font-family: var(--font);
  font-size: 9px;
  color: #eaf2e4;
}

/* Touch / action buttons */
.touch-controls {
  position: absolute;
  inset: 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 0 calc(22px + var(--safe-right)) calc(22px + var(--safe-bottom)) calc(22px + var(--safe-left));
  pointer-events: none;
}
.joystick {
  position: relative;
  width: 132px;
  height: 132px;
  border-radius: 50%;
  pointer-events: auto;
  touch-action: none;
  display: none;
  background: radial-gradient(circle, rgba(255,255,255,.05), rgba(0,0,0,.16) 70%);
  border: 1px solid rgba(139,224,164,.22);
  box-shadow: inset 0 0 20px rgba(0,0,0,.35);
}
.joystick-ring {
  position: absolute;
  inset: 20px;
  border-radius: 50%;
  border: 1px dashed rgba(139,224,164,.18);
}
.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, rgba(214,255,219,.55), rgba(84,160,108,.55) 55%, rgba(24,56,39,.8));
  border: 1px solid rgba(210,255,217,.4);
  box-shadow: 0 4px 14px rgba(0,0,0,.4), inset 0 0 12px rgba(255,255,255,.18);
  transition: transform .05s linear;
}
.action-group {
  display: flex;
  align-items: flex-end;
  gap: 13px;
  pointer-events: none;
}
.action-btn {
  position: relative;
  width: 78px;
  height: 78px;
  border-radius: 50%;
