    fringe.rotation.set(0.4, 0, 0.5);
    this.head.add(fringe);
    const earL = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.13, 0.08), skinDark);
    earL.position.set(-0.315, -0.01, 0);
    this.head.add(earL);
    const earR = earL.clone();
    earR.position.x = 0.315;
    this.head.add(earR);
    // No eyes, nose, or mouth: faceless low-poly hero.

    // Scarf
    const scarf = new THREE.Mesh(new THREE.TorusGeometry(0.25, 0.075, 4, 9), scarfMat);
    scarf.rotation.x = Math.PI / 2;
    scarf.position.y = 1.0;
    this.torso.add(scarf);
    this.scarfTail = new THREE.Group();
    this.scarfTail.position.set(-0.16, 0.98, -0.25);
    this.torso.add(this.scarfTail);
    const tail1 = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.48, 0.05), scarfMat);
    tail1.position.y = -0.23;
    tail1.rotation.z = 0.1;
    this.scarfTail.add(tail1);
    const tail2 = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.3, 0.04), scarfMat);
    tail2.position.set(-0.05, -0.57, -0.02);
    tail2.rotation.z = 0.25;
    this.scarfTail.add(tail2);

    // Arms
    const armGeo = new THREE.BoxGeometry(0.17, 0.6, 0.19);
    armGeo.translate(0, -0.3, 0);
    const handGeo = new THREE.IcosahedronGeometry(0.11, 0);
    handGeo.translate(0, -0.64, 0);
    const armPivot = (x, side) => {
      const g = new THREE.Group();
      g.position.set(x, 0.71, 0);
      const arm = new THREE.Mesh(armGeo, skin);
      arm.castShadow = true;
      const hand = new THREE.Mesh(handGeo, skinDark);
      hand.castShadow = true;
      const band = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.12, 0.21), leather);
      band.position.y = -0.47;
      g.add(arm, hand, band);
      this.torso.add(g);
      return g;
    };
    this.leftArm = armPivot(-0.5, -1);
    this.rightArm = armPivot(0.5, 1);

    // Pauldrons
    const pauldronGeo = new THREE.DodecahedronGeometry(0.25, 0);
    const pl = new THREE.Mesh(pauldronGeo, leather);
    pl.scale.set(1.15, 0.6, 1);
    pl.position.set(-0.52, 0.77, 0);
    pl.castShadow = true;
    this.torso.add(pl);
    const pr = new THREE.Mesh(pauldronGeo, metal);
    pr.scale.set(1.05, 0.55, 0.95);
    pr.position.set(0.53, 0.77, 0);
    pr.castShadow = true;
    this.torso.add(pr);
    for (let i = 0; i < 3; i++) {
      const spike = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.17, 4), metal);
      spike.position.set(0.48 + i * 0.07, 0.93 - i * 0.02, 0.04);
      spike.rotation.z = -0.25;
      this.torso.add(spike);
    }

    // Sword
    this.sword = new THREE.Group();
    this.sword.position.set(0, -0.68, 0);
    this.sword.rotation.set(0.18, 0, -0.08);
    this.rightArm.add(this.sword);
    const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.048, 0.052, 0.32, 6), leatherDark);
    grip.position.y = 0.06;
    this.sword.add(grip);
    const pommel = new THREE.Mesh(new THREE.IcosahedronGeometry(0.075, 0), gold);
    pommel.position.y = -0.11;
    this.sword.add(pommel);
    const guard = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.075, 0.11), gold);
    guard.position.y = 0.23;
    this.sword.add(guard);
    const blade = new THREE.Mesh(new THREE.BoxGeometry(0.115, 0.94, 0.038), metal);
    blade.position.y = 0.76;
    blade.castShadow = true;
    this.sword.add(blade);
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.078, 0.3, 4), metal);
    tip.position.y = 1.36;
    tip.rotation.y = Math.PI / 4;
    this.sword.add(tip);
    const edge = new THREE.Mesh(new THREE.BoxGeometry(0.025, 1.05, 0.045), bladeGlow);
    edge.position.set(0.04, 0.78, 0);
    this.sword.add(edge);

    this.bladeBase = new THREE.Object3D();
    this.bladeBase.position.set(0, 0.3, 0);
    this.sword.add(this.bladeBase);
    this.bladeTip = new THREE.Object3D();
    this.bladeTip.position.set(0, 1.5, 0);
    this.sword.add(this.bladeTip);

    this.model.traverse((o) => {
      if (o.isMesh) {
        o.castShadow = true;
        o.receiveShadow = true;
      }
    });

    this.baseY = 0;
  }

  setGame(game) { this.game = game; }

  get position() { return this.root.position; }
  get yawAngle() { return this.yaw; }

  resetToSpawn() {
    this.level = 1;
    this.xp = 0;
    this.xpNext = 35;
    this.maxHp = 100;
    this.hp = 100;
    this.maxMana = 100;
    this.mana = 100;
    this.attackPower = 15;
    this.dead = false;
    this.alive = true;
    this.deathT = 0;
    this.invuln = 0;
    this.attack = null;
    this.spin = null;
    this.spinOffset = 0;
    this.attackCooldown = 0;
    this.whirlCooldown = 0;
    this.comboStep = 0;
    this.comboTimer = 0;
    this.hurtTimer = 0;
    this.lastDamageAt = -99;
    this.velocity.set(0, 0, 0);
    this.knockback.set(0, 0, 0);
    this.yaw = Math.PI;
    this.root.position.set(0, this.world.height(0, 0), 0);
    this.model.position.set(0, 0, 0);
    this.model.rotation.set(0, this.yaw, 0);
    this.model.visible = true;
    this.root.visible = true;
    this.torso.rotation.set(0, 0, 0);
    this.leftArm.rotation.set(0.05, 0, -0.08);
    this.rightArm.rotation.set(-0.08, 0, 0.1);
    this.leftLeg.rotation.set(0, 0, 0);
    this.rightLeg.rotation.set(0, 0, 0);
    this.effects.clearTrail();
  }

  recalcStats() {
    this.maxHp = 100 + (this.level - 1) * 20;
    this.maxMana = 100 + (this.level - 1) * 8;
    this.attackPower = 15 + (this.level - 1) * 3.4;
    this.xpNext = this.level >= 10 ? 1 : Math.round(35 + (this.level - 1) * 21);
  }

  addXp(amount) {
    if (this.level >= 10) {
      this.xp = 1;
      return 0;
    }
    this.xp += amount;
    let ups = 0;
    while (this.xp >= this.xpNext && this.level < 10) {
      this.xp -= this.xpNext;
      this.level++;
      ups++;
      this.recalcStats();
      this.hp = Math.min(this.maxHp, this.hp + this.maxHp * 0.32);
      this.mana = Math.min(this.maxMana, this.mana + this.maxMana * 0.5);
    }
    if (this.level >= 10) this.xp = 1;
    return ups;
  }

  isBusy() { return Boolean(this.attack || this.spin); }
  isAttacking() { return Boolean(this.attack); }

  canAttack() {
    return !this.dead && !this.attack && !this.spin && this.attackCooldown <= 0;
  }

  startAttack() {
    if (!this.canAttack()) return false;
    const step = this.comboStep;
    this.comboStep = (this.comboStep + 1) % 3;
    const types = [
      { type: 'slash1', dur: 0.42, at: 0.4, mult: 1, range: 3.5, arc: 1.12, knock: 4.2 },
      { type: 'slash2', dur: 0.45, at: 0.4, mult: 1.18, range: 3.6, arc: 1.18, knock: 4.8 },
      { type: 'slam', dur: 0.62, at: 0.54, mult: 1.7, range: 4.1, arc: 0.95, knock: 7.5 }
    ];
    const def = types[step];
    this.attack = { ...def, t: 0, didHit: false, step };
    this.attackCooldown = def.dur * 0.82;
    this.comboTimer = 2.4;
    this.game?.onSwing(step);
    return true;
  }

  startWhirl() {
    if (this.dead || this.attack || this.spin || this.whirlCooldown > 0) return false;
    if (this.mana < this.manaCost) {
      this.game?.onNoMana();
      return false;
    }
    this.mana -= this.manaCost;
    this.spin = { t: 0, dur: 0.92, ticks: [0.14, 0.38, 0.62], nextTick: 0 };
    this.whirlCooldown = 3.4;
    this.attack = null;
    this.game?.onWhirlStart();
    return true;
  }

  takeDamage(amount, source) {
    if (this.dead || this.invuln > 0) return false;
    const dmg = Math.max(1, Math.round(amount));
    this.hp = Math.max(0, this.hp - dmg);
    this.invuln = 0.72;
    this.hurtTimer = 0.35;
    this.lastDamageAt = this.game?.time ?? 0;
    if (source) {
      const dx = this.root.position.x - source.x;
      const dz = this.root.position.z - source.z;
      const d = Math.hypot(dx, dz) || 1;
      this.knockback.set((dx / d) * 5.5, 0, (dz / d) * 5.5);
    }
    this.effects.playerHurt(new THREE.Vector3(this.root.position.x, this.root.position.y + 1.3, this.root.position.z));
    this.game?.onPlayerHurt(dmg);
    if (this.hp <= 0) {
      this.die();
      return true;
    }
    return true;
  }

  die() {
    if (this.dead) return;
    this.dead = true;
    this.alive = false;
    this.deathT = 0;
    this.attack = null;
    this.spin = null;
    this.velocity.set(0, 0, 0);
    this.knockback.set(0, 0, 0);
    this.game?.onPlayerDeath();
  }

  respawn() {
    this.resetToSpawn();
  }

  doMeleeHit() {
    if (!this.game?.enemyManager) return;
    const a = this.attack;
    const dmg = this.attackPower * a.mult;
    const hits = this.game.enemyManager.damageInArc(
      new THREE.Vector3(this.root.position.x, this.root.position.y + 1.1, this.root.position.z),
      this.yaw,
      a.range,
      Math.cos(a.arc / 2),
      dmg,
      a.knock,
      { source: 'hero', canCrit: a.step === 2 }
    );
    if (hits > 0) this.game?.onMeleeConnect(hits, a.step);
    this.game?.shake(a.step === 2 ? 0.2 : 0.09);
  }

  doWhirlHit() {
    if (!this.game?.enemyManager) return;
    const hits = this.game.enemyManager.damageInArc(
      new THREE.Vector3(this.root.position.x, this.root.position.y + 1.1, this.root.position.z),
      this.yaw,
      5.0,
      -1,
      this.attackPower * 0.82,
      8.5,
      { source: 'whirl', canCrit: false }
    );
    if (hits > 0) this.game?.onMeleeConnect(hits, 'whirl');
    this.game?.shake(0.16);
  }

  update(dt, input) {
    if (this.dead) {
      this.deathT += dt;
      const k = Math.min(1, this.deathT / 0.85);
      this.model.rotation.x = lerp(this.model.rotation.x, -1.45, k);
      this.model.position.y = lerp(this.model.position.y, -0.25, k);
      this.model.rotation.z = Math.sin(k * Math.PI) * 0.12;
      this.effects.clearTrail();
      return;
    }

    if (this.invuln > 0) this.invuln -= dt;
    if (this.hurtTimer > 0) this.hurtTimer -= dt;
    if (this.attackCooldown > 0) this.attackCooldown -= dt;
    if (this.whirlCooldown > 0) this.whirlCooldown -= dt;
    if (this.comboTimer > 0) this.comboTimer -= dt;
    else this.comboStep = 0;

    this.mana = Math.min(this.maxMana, this.mana + (5.2 + this.level * 0.32) * dt);
    const calm = (this.game?.time ?? 0) - this.lastDamageAt;
    if (calm > 7 && this.hp < this.maxHp) {
      this.hp = Math.min(this.maxHp, this.hp + (1.4 + this.level * 0.15) * dt);
    }

    const active = this.spin || this.attack;
    const speedScale = this.spin ? 0.25 : this.attack ? 0.52 : 1;
    let ix = input.x || 0;
    let iz = input.z || 0;
    const mag = Math.hypot(ix, iz);
    if (mag > 1) { ix /= mag; iz /= mag; }
    this.moving = mag > 0.08;

    const speed = 7.3;
    const targetVx = ix * speed * speedScale;
    const targetVz = iz * speed * speedScale;
    const accel = 1 - Math.exp(-dt * 13);
    this.velocity.x = lerp(this.velocity.x, targetVx, accel);
    this.velocity.z = lerp(this.velocity.z, targetVz, accel);

    this.knockback.multiplyScalar(Math.exp(-dt * 7));

    const px = this.root.position.x + (this.velocity.x + this.knockback.x) * dt;
    const pz = this.root.position.z + (this.velocity.z + this.knockback.z) * dt;
    this.root.position.x = px;
    this.root.position.z = pz;
    this.world.resolveCollisions(this.root.position, 0.42);
    this.root.position.y = this.world.height(this.root.position.x, this.root.position.z);

    if (this.moving && !this.attack && !this.spin) {
      const targetYaw = Math.atan2(this.velocity.x, this.velocity.z);
      this.yaw = angleLerp(this.yaw, targetYaw, 1 - Math.exp(-dt * 12));
    }

    // Locomotion animation
    if (this.moving) {
      this.walkPhase += dt * 10.2;
    } else {
      this.walkPhase += dt * 1.7;
    }
    const walkAmp = this.moving ? 0.72 : 0.06;
    const phase = this.walkPhase;
    const walkSin = Math.sin(phase);
    const bob = this.moving ? Math.abs(Math.sin(phase)) * 0.055 : Math.sin(phase) * 0.012;
    this.model.position.y = lerp(this.model.position.y, bob, 1 - Math.exp(-dt * 12));

    this.leftLeg.rotation.x = lerp(this.leftLeg.rotation.x, walkSin * walkAmp, 1 - Math.exp(-dt * 18));
    this.rightLeg.rotation.x = lerp(this.rightLeg.rotation.x, -walkSin * walkAmp, 1 - Math.exp(-dt * 18));
    this.leftArm.rotation.x = lerp(this.leftArm.rotation.x, -walkSin * walkAmp * 0.7 + (this.moving ? 0 : 0.06), 1 - Math.exp(-dt * 16));
    this.leftArm.rotation.z = -0.08;
    this.capePivot.rotation.x = lerp(this.capePivot.rotation.x, this.moving ? 0.22 + Math.sin(phase) * 0.05 : 0.04, 1 - Math.exp(-dt * 8));
    this.scarfTail.rotation.x = lerp(this.scarfTail.rotation.x, this.moving ? 0.35 : 0.08, 1 - Math.exp(-dt * 7));

    let bodyTwist = 0;
    let bodyPitch = 0;
    let rightArmX = this.moving ? walkSin * walkAmp * 0.55 : -0.08 + Math.sin(phase * 0.8) * 0.04;
    let rightArmY = 0;
    let rightArmZ = 0.1;
    let leftArmX = this.leftArm.rotation.x;

    if (this.attack) {
      const a = this.attack;
      a.t += dt;
      const p = clamp(a.t / a.dur, 0, 1);
      const wind = smooth(clamp(p / 0.22, 0, 1));
      const strike = smooth(clamp((p - 0.2) / 0.32, 0, 1));
      const recover = smooth(clamp((p - 0.54) / 0.46, 0, 1));
      if (a.step === 0) {
        rightArmX = lerp(lerp(lerp(0.2, -1.45, wind), -1.3, strike), 0.1, recover);
        rightArmY = lerp(lerp(lerp(0, 1.1, wind), -1.2, strike), 0, recover);
        bodyTwist = lerp(lerp(lerp(0, 0.42, wind), -0.52, strike), 0, recover);
      } else if (a.step === 1) {
        rightArmX = lerp(lerp(lerp(0.2, -1.35, wind), -1.5, strike), 0.1, recover);
        rightArmY = lerp(lerp(lerp(0, -1.15, wind), 1.25, strike), 0, recover);
        bodyTwist = lerp(lerp(lerp(0, -0.45, wind), 0.5, strike), 0, recover);
      } else {
        rightArmX = lerp(lerp(lerp(-0.1, -2.5, wind), -0.35, strike), 0.05, recover);
        rightArmY = 0;
        bodyPitch = lerp(lerp(0, -0.18, wind), 0.36, strike) * (1 - recover);
      }
      if (!a.didHit && p >= a.at) {
        a.didHit = true;
        this.doMeleeHit();
      }
      if (p >= 1) this.attack = null;
      this.head.rotation.x = bodyPitch * 0.35;
    } else {
      this.head.rotation.x = lerp(this.head.rotation.x, 0, 1 - Math.exp(-dt * 10));
    }

    if (this.spin) {
      const s = this.spin;
      s.t += dt;
      const p = clamp(s.t / s.dur, 0, 1);
      this.spinOffset = smooth(clamp(p / 0.82, 0, 1)) * Math.PI * 4;
      rightArmZ = 1.5;
      rightArmX = -0.35;
      rightArmY = 0;
      this.leftArm.rotation.z = -1.5;
      while (s.nextTick < s.ticks.length && p >= s.ticks[s.nextTick]) {
        s.nextTick++;
        this.doWhirlHit();
        this.effects.ring(new THREE.Vector3(this.root.position.x, this.root.position.y + 0.2, this.root.position.z), 0xbff4ff, 5.5, 0.5);
        this.game?.shake(0.14);
      }
      if (p >= 1) {
        this.spin = null;
        this.spinOffset = 0;
        this.leftArm.rotation.z = -0.08;
      }
    } else {
      this.leftArm.rotation.z = lerp(this.leftArm.rotation.z, -0.08, 1 - Math.exp(-dt * 12));
    }

    this.rightArm.rotation.x = lerp(this.rightArm.rotation.x, rightArmX, 1 - Math.exp(-dt * 25));
    this.rightArm.rotation.y = lerp(this.rightArm.rotation.y, rightArmY, 1 - Math.exp(-dt * 25));
    this.rightArm.rotation.z = lerp(this.rightArm.rotation.z, rightArmZ, 1 - Math.exp(-dt * 20));
    this.leftArm.rotation.x = lerp(this.leftArm.rotation.x, leftArmX, 1 - Math.exp(-dt * 10));
    this.torso.rotation.y = lerp(this.torso.rotation.y, bodyTwist, 1 - Math.exp(-dt * 18));
    this.torso.rotation.x = lerp(this.torso.rotation.x, bodyPitch, 1 - Math.exp(-dt * 14));
    this.model.rotation.y = this.yaw + this.spinOffset;

    // Sword trail
    if (this.attack || this.spin) {
      const performing = this.spin || (this.attack && this.attack.t / this.attack.dur > 0.16);
      if (performing) {
        const base = new THREE.Vector3();
        const tip = new THREE.Vector3();
        this.bladeBase.getWorldPosition(base);
        this.bladeTip.getWorldPosition(tip);
        this.effects.addTrail(base, tip);
      }
    }

    // Footsteps
    if (this.moving) {
      this.footstepTimer -= dt;
      if (this.footstepTimer <= 0) {
        this.footstepTimer = 0.31;
        this.effects.footstep(new THREE.Vector3(this.root.position.x, this.root.position.y + 0.05, this.root.position.z));
      }
    } else {
      this.footstepTimer = 0;
    }
  }
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/BufferGeometryUtils.js';

const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;

const TIERS = [
  { eye: 0x7fffd4, name: 'tulang pucat' },
  { eye: 0x9dffbd, name: 'tulang lumut' },
  { eye: 0xffd166, name: 'tulang emas' },
  { eye: 0xffa04d, name: 'tulang bakau' },
  { eye: 0xff5a5a, name: 'tulang neraka' }
];
function tierFor(level) {
  return TIERS[Math.min(TIERS.length - 1, Math.floor((level - 1) / 2))];
}

function paint(geometry, color, jitter = 0.06) {
  const count = geometry.attributes.position.count;
  const colors = new Float32Array(count * 3);
  const c = new THREE.Color(color);
  for (let i = 0; i < count; i++) {
    const j = 1 + (Math.random() * 2 - 1) * jitter;
    colors[i * 3] = c.r * j;
    colors[i * 3 + 1] = c.g * j;
    colors[i * 3 + 2] = c.b * j;
  }
  geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return geometry;
}

function transform(geometry, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0, sx = 1, sy = 1, sz = 1) {
  const m = new THREE.Matrix4();
  m.compose(new THREE.Vector3(x, y, z), new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz)), new THREE.Vector3(sx, sy, sz));
  geometry.applyMatrix4(m);
  return geometry;
}

let BODY_GEO = null;
let JAW_GEO = null;
let EYE_GEO = null;
let TAIL_GEO = null;
let AURA_GEO = null;
let GLOW_TEX = null;
let PROJECTILE_GEO = null;

function glowTexture() {
  if (GLOW_TEX) return GLOW_TEX;
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.25, 'rgba(255,255,255,0.65)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  GLOW_TEX = new THREE.CanvasTexture(c);
  GLOW_TEX.colorSpace = THREE.SRGBColorSpace;
  return GLOW_TEX;
}

function buildGeometry() {
  if (BODY_GEO) return;
  const parts = [];
  const skull = new THREE.IcosahedronGeometry(0.72, 1);
  skull.scale(1.02, 1.05, 0.9);
  parts.push(paint(skull, 0xe8e0ca, 0.055));

  // Brow ridge
  const brow = new THREE.BoxGeometry(0.9, 0.14, 0.32);
  transform(brow, 0, 0.25, 0.48, 0.08, 0, 0);
  parts.push(paint(brow, 0xd9cfb4, 0.04));

  // Sockets
  for (const x of [-0.26, 0.26]) {
    const socket = new THREE.IcosahedronGeometry(0.19, 1);
    transform(socket, x, 0.08, 0.58, 0, 0, 0, 1.05, 1.15, 0.45);
    parts.push(paint(socket, 0x171413, 0.03));
  }

  // Nose hollow
  const nose = new THREE.ConeGeometry(0.1, 0.2, 4);
  transform(nose, 0, -0.12, 0.63, Math.PI / 2, 0, 0.785);
  parts.push(paint(nose, 0x181513, 0.02));

  // Horns
  for (const side of [-1, 1]) {
    const horn = new THREE.ConeGeometry(0.13, 0.62, 4);
    transform(horn, side * 0.47, 0.63, -0.02, 0, 0, side * -0.55);
    parts.push(paint(horn, 0xb8ac91, 0.09));
    const horn2 = new THREE.ConeGeometry(0.075, 0.3, 4);
    transform(horn2, side * 0.63, 0.47, 0.12, 0, 0, side * -0.9);
    parts.push(paint(horn2, 0xa89c81, 0.08));
  }

  // Cheek spikes and little crown ridges
  for (const side of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      const spike = new THREE.ConeGeometry(0.045, 0.16, 4);
      transform(spike, side * 0.62, 0.28 - i * 0.2, 0.18 - i * 0.06, 0, 0, side * -1.0);
      parts.push(paint(spike, 0xcabfa4, 0.05));
    }
  }
  const crest = new THREE.ConeGeometry(0.09, 0.28, 4);
  transform(crest, 0, 0.74, -0.12, 0.2, 0, 0);
  parts.push(paint(crest, 0xc9bea2, 0.05));

  // Floating bone hands with claws
  for (const side of [-1, 1]) {
    const palm = new THREE.IcosahedronGeometry(0.15, 0);
    transform(palm, side * 0.88, -0.32, 0.16, 0, 0, 0, 1.1, 0.8, 1.2);
    parts.push(paint(palm, 0xd7cdb3, 0.07));
    for (let i = 0; i < 3; i++) {
      const claw = new THREE.ConeGeometry(0.045, 0.3, 4);
      transform(claw, side * 0.88 + (i - 1) * 0.1, -0.45, 0.38, 1.15, 0, side * -0.05);
      parts.push(paint(claw, 0xc5b99e, 0.05));
    }
  }
  BODY_GEO = mergeGeometries(parts);

  const jawParts = [];
  const jaw = new THREE.BoxGeometry(0.64, 0.18, 0.46);
  transform(jaw, 0, -0.1, 0.26, 0.05, 0, 0);
  jawParts.push(paint(jaw, 0xd8ceb5, 0.05));
  for (let i = 0; i < 5; i++) {
    const tooth = new THREE.ConeGeometry(0.045, 0.19, 4);
    transform(tooth, -0.24 + i * 0.12, 0.06, 0.45, Math.PI, 0, 0);
    jawParts.push(paint(tooth, 0xf2ead6, 0.03));
  }
  for (const side of [-1, 1]) {
    const fang = new THREE.ConeGeometry(0.055, 0.24, 4);
    transform(fang, side * 0.3, 0.04, 0.4, Math.PI, 0, 0);
    jawParts.push(paint(fang, 0xf4ecd8, 0.03));
  }
  JAW_GEO = mergeGeometries(jawParts);

  EYE_GEO = new THREE.SphereGeometry(0.095, 7, 5);
  TAIL_GEO = new THREE.ConeGeometry(0.56, 1.55, 7, 1, true);
  TAIL_GEO.rotateX(Math.PI);
  AURA_GEO = new THREE.TorusGeometry(0.82, 0.035, 4, 28);
  AURA_GEO.rotateX(Math.PI / 2);
  PROJECTILE_GEO = new THREE.IcosahedronGeometry(0.32, 1);
}

function levelAt(x, z) {
  const d = Math.hypot(x, z);
  return clamp(1 + Math.floor(d / 11), 1, 10);
}

class Enemy {
  constructor(manager, level, x, z, options = {}) {
    buildGeometry();
    this.manager = manager;
    this.world = manager.world;
    this.effects = manager.effects;
    this.audio = manager.audio;
    this.level = level;
    this.tier = tierFor(level);
    this.isCaster = options.caster ?? (level >= 3 && Math.random() < 0.42);
    this.home = new THREE.Vector3(x, 0, z);
    this.pos = new THREE.Vector3(x, 0, z);
    this.dead = false;
    this.dying = false;
    this.deathT = 0;
    this.removed = false;
    this.attackCooldown = 1 + Math.random() * 0.8;
    this.castCooldown = 2 + Math.random() * 2;
    this.castWindup = 0;
    this.attackWindup = 0;
    this.aggro = false;
    this.bobPhase = Math.random() * TAU;
    this.hoverHeight = 1.25 + 0.065 * level;
    this.scale = 0.82 + level * 0.037;
    this.radius = 0.62 * this.scale;
    this.maxHp = Math.round(30 + level * 17 + Math.pow(level, 1.35) * 4);
    this.hp = this.maxHp;
    this.maxMana = 100;
    this.mana = Math.random() * 55 + 25;
    this.damage = 5.2 + level * 2.45;
    this.speed = 2.1 + level * 0.16;
    this.xpReward = 8 + level * 4;
    this.scoreValue = 18 + level * 14;
    this.knock = new THREE.Vector3();
    this.flash = 0;
    this.lean = 0;
    this.buildMesh();
    this.updateBar(true);
    this.setPosition(x, z);
  }

  buildMesh() {
    const group = new THREE.Group();
    group.scale.setScalar(this.scale);
    this.group = group;

    this.boneMat = new THREE.MeshLambertMaterial({ vertexColors: true, flatShading: true, color: new THREE.Color().setHSL(0.1, 0.09, 0.94 - this.level * 0.012) });
    this.skull = new THREE.Mesh(BODY_GEO, this.boneMat);
    this.skull.castShadow = true;
    this.skull.receiveShadow = true;
    group.add(this.skull);

    this.jawPivot = new THREE.Group();
    this.jawPivot.position.set(0, -0.48, 0);
    this.jaw = new THREE.Mesh(JAW_GEO, this.boneMat);
    this.jaw.castShadow = true;
    this.jawPivot.add(this.jaw);
    group.add(this.jawPivot);

    this.eyeMat = new THREE.MeshBasicMaterial({ color: this.tier.eye });
    this.eyeL = new THREE.Mesh(EYE_GEO, this.eyeMat);
    this.eyeL.position.set(-0.26, 0.08, 0.63);
    this.eyeR = new THREE.Mesh(EYE_GEO, this.eyeMat);
    this.eyeR.position.set(0.26, 0.08, 0.63);
    group.add(this.eyeL, this.eyeR);

    this.eyeGlow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture(),
      color: this.tier.eye,
      transparent: true,
      opacity: 0.5,
      depthWrite: false,
      blending: THREE.AdditiveBlending
    }));
    this.eyeGlow.scale.set(1.5, 1.5, 1);
    this.eyeGlow.position.set(0, 0.1, 0.7);
    group.add(this.eyeGlow);

    this.tailMat = new THREE.MeshBasicMaterial({ color: this.isCaster ? 0x5c3681 : 0x2c3b33, transparent: true, opacity: 0.38, depthWrite: false, side: THREE.DoubleSide });
    this.tail = new THREE.Mesh(TAIL_GEO, this.tailMat);
    this.tail.position.y = -1.45;
    group.add(this.tail);

    if (this.isCaster) {
      this.auraMat = new THREE.MeshBasicMaterial({ color: 0xb07bff, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false });
      this.aura = new THREE.Mesh(AURA_GEO, this.auraMat);
      this.aura.position.y = -0.66;
      this.aura.rotation.x = 0.18;
      group.add(this.aura);
    }

    this.barCanvas = document.createElement('canvas');
    this.barCanvas.width = 256;
    this.barCanvas.height = 96;
    this.barCtx = this.barCanvas.getContext('2d');
    this.barTexture = new THREE.CanvasTexture(this.barCanvas);
    this.barTexture.colorSpace = THREE.SRGBColorSpace;
    this.barTexture.minFilter = THREE.LinearFilter;
    this.barSprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.barTexture,
      transparent: true,
      depthWrite: false,
      depthTest: false,
      fog: false
    }));
    this.barSprite.scale.set(2.6, 0.975, 1);
    this.barSprite.position.y = 1.88;
    this.barSprite.renderOrder = 6;
    group.add(this.barSprite);

    this.manager.scene.add(group);
  }

  setPosition(x, z) {
    this.pos.x = x;
    this.pos.z = z;
    this.home.x = x;
    this.home.z = z;
    this.group.position.set(x, this.world.height(x, z) + this.hoverHeight, z);
  }

  updateBar(force = false) {
    const hpRatio = clamp(this.hp / this.maxHp, 0, 1);
    const mpRatio = clamp(this.mana / this.maxMana, 0, 1);
    if (!force && Math.abs(hpRatio - (this.lastHpRatio ?? -1)) < 0.005 && Math.abs(mpRatio - (this.lastMpRatio ?? -1)) < 0.02) return;
    this.lastHpRatio = hpRatio;
    this.lastMpRatio = mpRatio;
    const ctx = this.barCtx;
    const w = 256, h = 96;
    ctx.clearRect(0, 0, w, h);
    // plate
    ctx.fillStyle = 'rgba(6,12,9,0.72)';
    ctx.beginPath();
    ctx.moveTo(10, 8);
    ctx.lineTo(w - 10, 8);
    ctx.lineTo(w - 18, 28);
    ctx.lineTo(w - 18, h - 14);
    ctx.lineTo(w - 34, h - 4);
    ctx.lineTo(28, h - 4);
    ctx.lineTo(8, h - 20);
    ctx.lineTo(8, 22);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(170,210,175,0.28)';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // level diamond
    ctx.save();
    ctx.translate(31, 47);
    ctx.rotate(Math.PI / 4);
    const tierColor = '#' + this.tier.eye.toString(16).padStart(6, '0');
    ctx.fillStyle = 'rgba(12,20,15,0.95)';
    ctx.strokeStyle = tierColor;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.rect(-15, -15, 30, 30);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    ctx.fillStyle = tierColor;
    ctx.font = 'bold 17px "Trebuchet MS", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(String(this.level), 31, 48);

    const barX = 55, barW = 184;
    // hp
    ctx.fillStyle = 'rgba(0,0,0,0.65)';
    ctx.fillRect(barX - 2, 26, barW + 4, 23);
    const hpGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
    if (hpRatio > 0.55) {
      hpGrad.addColorStop(0, '#4fcf74');
      hpGrad.addColorStop(1, '#a6e86d');
    } else if (hpRatio > 0.25) {
      hpGrad.addColorStop(0, '#e6a63b');
      hpGrad.addColorStop(1, '#f4d160');
    } else {
      hpGrad.addColorStop(0, '#d83f35');
      hpGrad.addColorStop(1, '#ff7a5c');
    }
    ctx.fillStyle = hpGrad;
    ctx.fillRect(barX, 28, barW * hpRatio, 19);
    ctx.fillStyle = 'rgba(255,255,255,0.22)';
    ctx.fillRect(barX, 28, barW * hpRatio, 6);
    ctx.strokeStyle = 'rgba(230,240,225,0.35)';
    ctx.lineWidth = 1;
    ctx.strokeRect(barX - 0.5, 27.5, barW + 1, 20);

    // mana
    ctx.fillStyle = 'rgba(0,0,0,0.65)';
    ctx.fillRect(barX - 2, 55, barW + 4, 15);
    const mpGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
    mpGrad.addColorStop(0, '#2c78d8');
    mpGrad.addColorStop(1, '#78d4ff');
    ctx.fillStyle = mpGrad;
    ctx.fillRect(barX, 57, barW * mpRatio, 11);
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.fillRect(barX, 57, barW * mpRatio, 3);
    ctx.strokeStyle = 'rgba(170,220,255,0.28)';
    ctx.strokeRect(barX - 0.5, 56.5, barW + 1, 12);

    ctx.fillStyle = 'rgba(210,225,205,0.7)';
    ctx.font = 'bold 9px "Trebuchet MS", sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(this.isCaster ? 'PENYIHIR' : 'TENGKORAK', w - 25, 20);
    this.barTexture.needsUpdate = true;
  }

  takeDamage(amount, fromPos, knock = 4, options = {}) {
    if (this.dead || this.dying) return { dead: false, damage: 0, crit: false };
    let dmg = amount * (0.9 + Math.random() * 0.2);
    let crit = false;
    if (options.canCrit && Math.random() < 0.22) {
      crit = true;
      dmg *= 1.65;
    }
    dmg = Math.max(1, Math.round(dmg));
    this.hp -= dmg;
    this.flash = 0.14;
    this.aggro = true;
    if (fromPos) {
      const dx = this.pos.x - fromPos.x;
      const dz = this.pos.z - fromPos.z;
      const d = Math.hypot(dx, dz) || 1;
      this.knock.set((dx / d) * knock, 0, (dz / d) * knock);
    }
    this.lastHpRatio = -1;
    this.updateBar();
    const hitPos = new THREE.Vector3(this.group.position.x, this.group.position.y + 0.2, this.group.position.z);
    if (crit) {
      this.effects.crit(hitPos);
      this.audio?.hit(true);
    } else {
      this.effects.hit(hitPos, this.tier.eye, 14);
      this.audio?.hit(false);
    }
    this.manager.onHit?.(this, dmg, crit);
    if (this.hp <= 0) {
      this.die();
      return { dead: true, damage: dmg, crit };
    }
    return { dead: false, damage: dmg, crit };
  }

  die() {
    if (this.dying) return;
    this.dying = true;
    this.dead = true;
    this.hp = 0;
    this.deathT = 0;
    this.barSprite.visible = false;
    this.aura && (this.aura.visible = false);
    this.eyeGlow.material.opacity = 0.15;
    this.manager.handleKill(this);
  }

  startCast() {
    if (!this.isCaster || this.mana < 45 || this.castCooldown > 0 || this.castWindup > 0) return false;
    this.castWindup = 0.62;
    this.mana -= 45;
    this.castCooldown = 4.4 + Math.random() * 1.5;
    this.lastMpRatio = -1;
    this.updateBar();
    this.audio?.cast();
    this.effects.cast(new THREE.Vector3(this.group.position.x, this.group.position.y - 0.2, this.group.position.z), 0xb07bff);
    return true;
  }

  update(dt, player, active) {
    if (this.dying) {
      this.deathT += dt;
      const k = clamp(this.deathT / 0.8, 0, 1);
      this.group.rotation.z += dt * 2.6;
      this.group.position.y -= dt * 1.3;
      this.group.scale.setScalar(this.scale * (1 - k * 0.55));
      this.skull.material.opacity = 1 - k;
      this.tailMat.opacity = 0.38 * (1 - k);
      this.eyeGlow.material.opacity = 0.2 * (1 - k);
      if (this.deathT > 0.85) this.removed = true;
      return;
    }
    if (this.removed) return;

    this.bobPhase += dt * (1.7 + this.level * 0.08);
    this.flash = Math.max(0, this.flash - dt);
    this.boneMat.emissive.setHex(this.flash > 0 ? 0x8a6a38 : 0x000000);
    this.boneMat.emissiveIntensity = this.flash > 0 ? 1.4 : 1;

    const dx = player.position.x - this.pos.x;
    const dz = player.position.z - this.pos.z;
    const dist = Math.hypot(dx, dz);
    const angle = Math.atan2(dx, dz);
    const targetHover = this.hoverHeight + Math.sin(this.bobPhase) * 0.12;
    const groundY = this.world.height(this.pos.x, this.pos.z);

    this.attackCooldown -= dt;
    this.castCooldown -= dt;
    this.mana = Math.min(this.maxMana, this.mana + dt * (3.5 + this.level * 0.22));
    if (Math.floor(this.mana / 2) !== Math.floor((this.mana + dt * 4) / 2)) this.updateBar();

    let moving = false;
    let targetLean = 0;

    if (active && !player.dead && dist < 24) {
      this.aggro = true;
    }

    if (this.aggro && active && !player.dead) {
      // Face player smoothly
      this.group.rotation.y = this.angleLerp(this.group.rotation.y, angle, 1 - Math.exp(-dt * 7));

      if (this.castWindup > 0) {
        this.castWindup -= dt;
        this.eyeGlow.scale.setScalar(1.5 + Math.sin(this.bobPhase * 8) * 0.25);
        this.eyeMat.color.setHex(this.castWindup > 0.2 ? 0xe6c6ff : this.tier.eye);
        targetHover += 0.25;
        if (this.castWindup <= 0) {
          this.mana -= 0;
          this.manager.spawnProjectile(this, player);
          this.eyeMat.color.setHex(this.tier.eye);
        }
      } else if (this.attackWindup > 0) {
        this.attackWindup -= dt;
        this.jawPivot.rotation.x = lerp(this.jawPivot.rotation.x, 0.55, 1 - Math.exp(-dt * 15));
        targetHover += 0.12;
        if (this.attackWindup <= 0) {
          this.jawPivot.rotation.x = -0.05;
          this.attackCooldown = 1.55 + Math.random() * 0.4;
          if (dist < 3.5) {
            player.takeDamage(this.damage, this.pos);
          }
          this.effects.burst(new THREE.Vector3(this.group.position.x, this.group.position.y - 0.2, this.group.position.z), this.tier.eye, 10, 3);
        }
      } else {
        // Ranged caster behavior
        if (this.isCaster && this.mana >= 45 && this.castCooldown <= 0 && dist > 4.2 && dist < 15) {
          this.startCast();
        } else if (dist > 2.6) {
          // Chase with slight separation
          let sx = 0, sz = 0;
          for (const other of this.manager.enemies) {
            if (other === this || other.dying) continue;
            const ox = this.pos.x - other.pos.x;
            const oz = this.pos.z - other.pos.z;
            const od = ox * ox + oz * oz;
            if (od < 3.2 && od > 0.001) {
              const inv = 1 / Math.sqrt(od);
              sx += ox * inv;
              sz += oz * inv;
            }
          }
          const nx = dx / (dist || 1) + sx * 0.55;
          const nz = dz / (dist || 1) + sz * 0.55;
          const len = Math.hypot(nx, nz) || 1;
          const spd = this.speed * (dist > 5 ? 1 : 0.72);
          this.pos.x += (nx / len) * spd * dt;
          this.pos.z += (nz / len) * spd * dt;
          moving = true;
          targetLean = -0.13;
        } else if (this.attackCooldown <= 0) {
          this.attackWindup = 0.42;
          this.effects.cast(new THREE.Vector3(this.group.position.x, this.group.position.y - 0.3, this.group.position.z), 0xff7a5c);
        }
      }
    } else {
      // Idle drift around home
      const t = performance.now() * 0.0002 + this.bobPhase;
      this.pos.x += Math.cos(t) * 0.14 * dt;
      this.pos.z += Math.sin(t * 1.2) * 0.14 * dt;
      this.group.rotation.y = this.angleLerp(this.group.rotation.y, this.homeAngle ?? this.group.rotation.y, 1 - Math.exp(-dt * 2));
      this.jawPivot.rotation.x = lerp(this.jawPivot.rotation.x, Math.sin(this.bobPhase * 0.8) * 0.06, 1 - Math.exp(-dt * 5));
    }

    this.jawPivot.rotation.x = lerp(this.jawPivot.rotation.x, this.attackWindup > 0 || this.castWindup > 0 ? 0.5 : 0.02, 1 - Math.exp(-dt * 10));

    this.knock.multiplyScalar(Math.exp(-dt * 6));
    this.pos.x += this.knock.x * dt;
    this.pos.z += this.knock.z * dt;

    const dr = Math.hypot(this.pos.x, this.pos.z);
    if (dr > 109) { this.pos.x *= 109 / dr; this.pos.z *= 109 / dr; }

    this.group.position.x = this.pos.x;
    this.group.position.z = this.pos.z;
    this.group.position.y = lerp(this.group.position.y, groundY + targetHover, 1 - Math.exp(-dt * 8));
    this.group.rotation.z = lerp(this.group.rotation.z, targetLean + Math.sin(this.bobPhase * 1.3) * 0.025, 1 - Math.exp(-dt * 5));

    this.eyeGlow.material.opacity = 0.35 + Math.sin(this.bobPhase * 2.4) * 0.1 + (this.castWindup > 0 ? 0.4 : 0);
    this.eyeGlow.scale.setScalar(1.4 + Math.sin(this.bobPhase * 2.4) * 0.12 + (this.castWindup > 0 ? 0.5 : 0));
    if (this.aura) {
      this.aura.rotation.y += dt * 1.4;
      this.auraMat.opacity = 0.35 + Math.sin(this.bobPhase * 1.8) * 0.15;
    }
    this.barSprite.visible = dist < 46;
    if (this.barSprite.visible) {
      const s = 2.6;
      this.barSprite.scale.set(s, 0.975, 1);
    }
  }

  angleLerp(a, b, t) {
    let d = ((b - a + Math.PI) % TAU + TAU) % TAU - Math.PI;
    return a + d * t;
  }

  dispose() {
    this.manager.scene.remove(this.group);
    this.barTexture.dispose();
    this.boneMat.dispose();
    this.eyeMat.dispose();
    this.tailMat.dispose();
    this.eyeGlow.material.dispose();
    this.barSprite.material.dispose();
    this.auraMat?.dispose();
  }
}

export class EnemyManager {
  constructor(scene, world, effects, audio) {
    this.scene = scene;
    this.world = world;
    this.effects = effects;
    this.audio = audio;
    this.enemies = [];
    this.projectiles = [];
    this.onKill = null;
    this.onHit = null;
    this.spawnTimer = 0;
    this.maxEnemies = window.matchMedia('(pointer: coarse)').matches || window.innerWidth < 760 ? 16 : 24;
    this.projectileGeo = new THREE.IcosahedronGeometry(0.3, 1);
    this.projectileMatProto = new THREE.MeshBasicMaterial({ color: 0xb37dff });
    this.projectileGlowTex = glowTexture();
    this.spawnInitial();
  }

  spawnInitial() {
    const pts = [
      [-4, -12], [7.5, -16], [-12, -21], [3, -28], [13.5, -9], [-19, -5.5], [17, -27],
      [-9, -34], [24, -33], [-26, -27], [30, -6], [-32, 11], [18, 14], [-12, 26],
      [36, 21], [-38, 34], [8, 41], [45, -31], [-45, -42], [28, 48], [-20, 55],
      [55, 25], [-58, 40], [65, -10], [18, -58], [-60, -55]
    ];
    const count = Math.min(pts.length, this.maxEnemies);
    for (let i = 0; i < count; i++) {
      const [x, z] = pts[i];
      const level = levelAt(x, z);
      const enemy = new Enemy(this, level, x, z, { caster: i % 3 === 1 });
      this.enemies.push(enemy);
    }
  }

  findSpawnSpot(player) {
    for (let i = 0; i < 18; i++) {
      const a = Math.random() * TAU;
      const dist = 26 + Math.random() * 16;
      const x = player.position.x + Math.cos(a) * dist;
      const z = player.position.z + Math.sin(a) * dist;
      const dOrigin = Math.hypot(x, z);
      if (dOrigin > 106) continue;
      if (dOrigin < 13 && player.position.length() < 6) continue;
      return { x, z };
    }
    const a = Math.random() * TAU;
    return { x: Math.cos(a) * 60, z: Math.sin(a) * 60 };
  }

  spawnOne(player) {
    const spot = this.findSpawnSpot(player);
    const level = levelAt(spot.x, spot.z);
    const enemy = new Enemy(this, level, spot.x, spot.z, { caster: Math.random() < 0.4 });
    this.enemies.push(enemy);
    return enemy;
  }

  spawnProjectile(enemy, player) {
    const origin = new THREE.Vector3(enemy.group.position.x, enemy.group.position.y + 0.05, enemy.group.position.z);
    const target = new THREE.Vector3(player.position.x, player.position.y + 1.15, player.position.z);
    const dir = target.sub(origin).normalize();
    const mesh = new THREE.Mesh(this.projectileGeo, this.projectileMatProto.clone());
    mesh.material.color.setHex(enemy.tier.eye);
    mesh.position.copy(origin);
    mesh.scale.setScalar(0.9 + enemy.level * 0.03);
    this.scene.add(mesh);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.projectileGlowTex,
      color: enemy.tier.eye,
      transparent: true,
      opacity: 0.85,
      depthWrite: false,
      blending: THREE.AdditiveBlending
    }));
    glow.scale.set(1.7, 1.7, 1);
    mesh.add(glow);
    this.projectiles.push({
      mesh,
      dir,
      speed: 9.2,
      damage: enemy.damage * 0.82,
      life: 3.2,
      radius: 1.05,
      color: enemy.tier.eye,
      trailT: 0
    });
    this.audio?.cast();
  }

  updateProjectiles(dt, player) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      p.mesh.position.addScaledVector(p.dir, p.speed * dt);
      p.mesh.rotation.x += dt * 5;
      p.mesh.rotation.y += dt * 7;
      p.trailT -= dt;
      if (p.trailT <= 0) {
        p.trailT = 0.05;
        this.effects.spark.spawn(p.mesh.position, { count: 1, color: p.color, color2: 0xffffff, speedMin: 0.1, speedMax: 1, sizeMin: 0.1, sizeMax: 0.2, lifeMin: 0.2, lifeMax: 0.45, gravity: 0, drag: 2, alpha: 0.7 });
      }
      const groundY = this.world.height(p.mesh.position.x, p.mesh.position.z);
      let hit = false;
      if (!player.dead) {
        const dx = p.mesh.position.x - player.position.x;
        const dy = p.mesh.position.y - (player.position.y + 1.1);
        const dz = p.mesh.position.z - player.position.z;
        if (dx * dx + dy * dy + dz * dz < p.radius * p.radius) {
          player.takeDamage(p.damage, p.mesh.position);
          hit = true;
        }
      }
      if (p.mesh.position.y < groundY + 0.15) hit = true;
      if (p.life <= 0) hit = true;
      if (hit) {
        this.effects.burst(p.mesh.position, p.color, 22, 5.5);
        this.effects.ring(new THREE.Vector3(p.mesh.position.x, Math.max(groundY, p.mesh.position.y), p.mesh.position.z), p.color, 2.4, 0.35);
        this.audio?.impact();
        this.scene.remove(p.mesh);
        p.mesh.material.dispose();
        p.mesh.children[0]?.material.dispose();
        this.projectiles.splice(i, 1);
      }
    }
  }

  update(dt, player, camera, active = true) {
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      e.update(dt, player, active);
      if (e.removed) {
        e.dispose();
        this.enemies.splice(i, 1);
      }
    }
    this.updateProjectiles(dt, player);
    if (active) {
      this.spawnTimer -= dt;
      if (this.spawnTimer <= 0 && this.enemies.length < this.maxEnemies) {
        this.spawnOne(player);
        this.spawnTimer = 2.6 + Math.random() * 2.2;
      }
    }
  }

  damageInArc(origin, yaw, range, arcCos, damage, knock, options = {}) {
    let hits = 0;
    const fx = Math.sin(yaw);
    const fz = Math.cos(yaw);
    for (const e of this.enemies) {
      if (e.dead || e.dying) continue;
      const dx = e.pos.x - origin.x;
      const dz = e.pos.z - origin.z;
      const dist = Math.hypot(dx, dz);
      if (dist > range + e.radius) continue;
      if (arcCos > -0.9 && dist > 0.001) {
        const dot = (dx / dist) * fx + (dz / dist) * fz;
        if (dot < arcCos) continue;
      }
      e.takeDamage(damage, origin, knock, options);
      hits++;
    }
    return hits;
  }

  handleKill(enemy) {
    this.effects.enemyDeath(new THREE.Vector3(enemy.group.position.x, enemy.group.position.y, enemy.group.position.z), enemy.tier.eye, enemy.level >= 7);
    this.audio?.enemyDie(enemy.level >= 7);
    this.onKill?.(enemy);
  }

  resetAroundSpawn() {
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      const d = Math.hypot(e.pos.x, e.pos.z);
      if (d < 23 || e.dying) {
        if (!e.dying) {
          e.effects.burst(new THREE.Vector3(e.group.position.x, e.group.position.y, e.group.position.z), 0x8be0a4, 10, 2.5);
        }
        this.scene.remove(e.group);
        e.dispose();
        this.enemies.splice(i, 1);
      }
    }
    this.spawnTimer = 2.2;
    this.projectiles.forEach((p) => {
      this.scene.remove(p.mesh);
      p.mesh.material.dispose();
      p.mesh.children[0]?.material.dispose();
    });
    this.projectiles.length = 0;
    while (this.enemies.length < 5) {
      const a = Math.random() * TAU;
      const dist = 26 + Math.random() * 10;
      const level = levelAt(Math.cos(a) * dist, Math.sin(a) * dist);
      const enemy = new Enemy(this, level, Math.cos(a) * dist, Math.sin(a) * dist);
      this.enemies.push(enemy);
    }
  }
}

import { WORLD_RADIUS } from './world.js';

const $ = (id) => document.getElementById(id);

const ZONE_NAMES = [
  'PADANG TENANG',
  'RERUMPUT LIAR',
  'HUTAN GELAP',
  'TANAH TERKUTUK',
  'AMBANG MAUT'
];

function format(n) {
  return Math.floor(n).toLocaleString('id-ID');
}

export class UI {
  constructor() {
    this.el = {
      hud: $('hud'),
      hpFill: $('hp-fill'),
      hpText: $('hp-text'),
      mpFill: $('mp-fill'),
      mpText: $('mp-text'),
      xpFill: $('xp-fill'),
      xpText: $('xp-text'),
      xpRow: document.querySelector('.xp-row'),
      levelBadge: $('level-badge'),
      playerRank: $('player-rank'),
      score: $('score-value'),
      best: $('best-value'),
      startBest: $('start-best'),
      multiplier: $('multiplier'),
      comboToast: $('combo-toast'),
      zoneLabel: $('zone-label'),
      zoneName: $('zone-name'),
      zoneFill: $('zone-fill'),
      zoneDistance: $('zone-distance'),
      radar: $('radar'),
      start: $('start-screen'),
      startBtn: $('start-btn'),
      death: $('death-screen'),
      deathScore: $('death-score'),
      deathBest: $('death-best'),
      deathLevel: $('death-level'),
      deathKills: $('death-kills'),
      respawn: $('respawn-btn'),
      mute: $('mute-btn'),
      danger: $('danger-overlay'),
      flash: $('hit-flash'),
      damageLayer: $('damage-layer'),
      toastLayer: $('toast-layer'),
      loading: $('loading'),
      joystick: $('joystick'),
      joystickKnob: $('joystick-knob'),
      attackBtn: $('attack-btn'),
      skillBtn: $('skill-btn'),
      skillCd: $('skill-cd'),
      touch: $('touch-controls')
    };
    this.radarCtx = this.el.radar.getContext('2d');
    this.move = { x: 0, z: 0 };
    this.attackHeld = false;
    this.joystickPointer = null;
    this.damage = [];
    this.lastHud = 0;
    this.lastRadar = 0;
    this.lastScore = -1;
    this.lastZone = -1;
    this.lowHp = false;
    this.handlers = {};
    this.bind();
  }

  bind() {
    this.el.startBtn.addEventListener('click', (e) => {
      e.preventDefault();
      this.handlers.onStart?.();
    });
    this.el.respawn.addEventListener('click', (e) => {
      e.preventDefault();
      this.handlers.onRespawn?.();
    });
    this.el.mute.addEventListener('click', (e) => {
      e.preventDefault();
      this.handlers.onMute?.();
    });

    this.el.attackBtn.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.attackHeld = true;
      this.el.attackBtn.setPointerCapture?.(e.pointerId);
      this.handlers.onAttack?.();
    });
    const endAttack = (e) => {
      e?.preventDefault?.();
      this.attackHeld = false;
    };
    this.el.attackBtn.addEventListener('pointerup', endAttack);
    this.el.attackBtn.addEventListener('pointercancel', endAttack);
    this.el.attackBtn.addEventListener('lostpointercapture', () => { this.attackHeld = false; });

    this.el.skillBtn.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.handlers.onSkill?.();
    });

    const joy = this.el.joystick;
    const updateJoy = (e) => {
      const rect = joy.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      let dx = e.clientX - cx;
      let dy = e.clientY - cy;
      const max = rect.width * 0.34;
      const d = Math.hypot(dx, dy);
      if (d > max) { dx = (dx / d) * max; dy = (dy / d) * max; }
      this.el.joystickKnob.style.transform = `translate(${dx}px, ${dy}px)`;
      this.move.x = dx / max;
      this.move.z = dy / max;
    };
    joy.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.joystickPointer = e.pointerId;
      joy.setPointerCapture?.(e.pointerId);
      updateJoy(e);
    });
    joy.addEventListener('pointermove', (e) => {
      if (e.pointerId !== this.joystickPointer) return;
      e.preventDefault();
      updateJoy(e);
    });
    const endJoy = (e) => {
      if (e && e.pointerId !== this.joystickPointer) return;
      this.joystickPointer = null;
      this.move.x = 0;
      this.move.z = 0;
      this.el.joystickKnob.style.transform = 'translate(0px, 0px)';
    };
    joy.addEventListener('pointerup', endJoy);
    joy.addEventListener('pointercancel', endJoy);
    joy.addEventListener('lostpointercapture', () => endJoy());

    window.addEventListener('keydown', (e) => {
      if (e.code === 'Enter' && !this.el.start.classList.contains('leaving')) {
        this.handlers.onStart?.();
      }
      if (e.code === 'KeyR' && !this.el.death.classList.contains('hidden')) {
        this.handlers.onRespawn?.();
      }
    });
  }

  setHandlers(handlers) { Object.assign(this.handlers, handlers); }

  setBest(best) {
    this.el.best.textContent = format(best);
    this.el.startBest.textContent = format(best);
  }

  ready() {
    this.el.loading.classList.add('done');
    setTimeout(() => this.el.loading.classList.add('hidden'), 800);
  }

  showStart() {
    this.el.start.classList.remove('leaving');
    document.body.classList.remove('started');
  }

  hideStart() {
    this.el.start.classList.add('leaving');
    document.body.classList.add('started');
  }

  showDeath(stats) {
    this.el.deathScore.textContent = format(stats.score);
    this.el.deathBest.textContent = format(stats.best);
    this.el.deathLevel.textContent = String(stats.level);
    this.el.deathKills.textContent = String(stats.kills);
    this.el.death.classList.remove('hidden');
    document.body.classList.add('dying');
  }

  hideDeath() {
    this.el.death.classList.add('hidden');
    document.body.classList.remove('dying');
  }

  setMuted(muted) {
    document.body.classList.toggle('muted', muted);
    this.el.mute.setAttribute('aria-label', muted ? 'Suara mati' : 'Suara aktif');
  }

  getInput() {
    return this.move;
  }

  updateHUD(state, dt) {
    const { hero, score, best, combo, comboTime } = state;
    this.lastHud += dt;
    if (this.lastHud < 0.05) return;
    this.lastHud = 0;
    const hpRatio = Math.max(0, hero.hp / hero.maxHp);
    const mpRatio = Math.max(0, hero.mana / hero.maxMana);
    this.el.hpFill.style.width = `${hpRatio * 100}%`;
    this.el.mpFill.style.width = `${mpRatio * 100}%`;
    this.el.hpText.textContent = `${Math.ceil(hero.hp)} / ${Math.round(hero.maxHp)}`;
    this.el.mpText.textContent = `${Math.floor(hero.mana)} / ${Math.round(hero.maxMana)}`;
    this.el.levelBadge.textContent = String(hero.level);
    this.el.xpFill.style.width = `${hero.level >= 10 ? 100 : Math.min(100, (hero.xp / hero.xpNext) * 100)}%`;
    this.el.xpText.textContent = hero.level >= 10 ? 'MAX LEVEL' : `${Math.floor(hero.xp)} / ${hero.xpNext} XP`;
    this.el.xpRow.classList.toggle('maxed', hero.level >= 10);

    const ranks = ['PEDANG PADANG', 'PEMBURU TULANG', 'PENJAGA PADANG', 'LEGENDA PADANG'];
    this.el.playerRank.textContent = hero.level >= 10 ? ranks[3] : hero.level >= 7 ? ranks[2] : hero.level >= 4 ? ranks[1] : ranks[0];

    if (score !== this.lastScore) {
      this.lastScore = score;
      this.el.score.textContent = format(score);
      if (score > 0) {
        this.el.score.animate(
          [{ transform: 'scale(1.15)', filter: 'brightness(1.6)' }, { transform: 'scale(1)', filter: 'brightness(1)' }],
          { duration: 180, easing: 'ease-out' }
        );
      }
    }
    this.el.best.textContent = format(Math.max(best, score));

    const mult = 1 + Math.min(combo, 10) * 0.1;
    this.el.multiplier.textContent = `KOMBO x${mult.toFixed(1)}`;
    this.el.multiplier.classList.toggle('on', combo > 0 && comboTime > 0);
    this.el.comboToast.textContent = combo >= 2 ? `${combo} HIT COMBO` : '';
    this.el.comboToast.classList.toggle('on', combo >= 2 && comboTime > 0);

    const dist = Math.hypot(hero.position.x, hero.position.z);
    const zone = Math.min(10, 1 + Math.floor(dist / 11));
    this.el.zoneLabel.textContent = `ZONA ${zone}`;
    this.el.zoneName.textContent = ZONE_NAMES[Math.min(ZONE_NAMES.length - 1, Math.floor((zone - 1) / 2))];
    this.el.zoneFill.style.width = `${Math.min(100, (dist / WORLD_RADIUS) * 100)}%`;
    this.el.zoneDistance.textContent = `${Math.round(dist)} m dari spawn`;

    const danger = hpRatio < 0.32 && !hero.dead;
    this.lowHp = danger;
    this.el.danger.style.opacity = danger ? `${0.55 + Math.sin(performance.now() * 0.006) * 0.2}` : '0';

    const skillReady = hero.whirlCooldown <= 0 && hero.mana >= hero.manaCost;
    this.el.skillBtn.classList.toggle('no-mana', !skillReady);
    const cd = Math.max(0, hero.whirlCooldown) / 3.4;
    this.el.skillCd.style.setProperty('--cd', `${cd * 100}%`);
    this.el.skillCd.classList.toggle('on', cd > 0.01);
    this.el.attackBtn.classList.toggle('no-mana', hero.dead);

    if (this.lastZone !== zone) {
      if (this.lastZone !== -1) this.handlers.onZoneChange?.(zone);
      this.lastZone = zone;
    }
  }

  drawRadar(hero, enemies) {
    const ctx = this.radarCtx;
    const w = this.el.radar.width;
    const h = this.el.radar.height;
    const cx = w / 2;
    const cy = h / 2;
    const scale = (w / 2 - 10) / WORLD_RADIUS;
    ctx.clearRect(0, 0, w, h);

    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, w / 2 - 2, 0, Math.PI * 2);
    ctx.clip();
    const grad = ctx.createRadialGradient(cx, cy, 4, cx, cy, w / 2);
    grad.addColorStop(0, 'rgba(27,62,42,0.82)');
    grad.addColorStop(1, 'rgba(5,16,11,0.92)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);

    // zone rings
    ctx.strokeStyle = 'rgba(139,224,164,0.1)';
    ctx.lineWidth = 1;
    for (let r = 22; r <= 110; r += 22) {
      ctx.beginPath();
      ctx.arc(cx, cy, r * scale, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(255,209,102,0.18)';
    ctx.setLineDash([4, 7]);
    ctx.beginPath();
    ctx.arc(cx, cy, WORLD_RADIUS * scale, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // spawn crystal
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(Math.PI / 4);
    ctx.fillStyle = 'rgba(120,245,208,0.9)';
    ctx.shadowColor = '#78f5d0';
    ctx.shadowBlur = 10;
    ctx.fillRect(-4, -4, 8, 8);
    ctx.restore();

    // enemies
    for (const e of enemies) {
      if (e.dead) continue;
      const ex = cx + e.pos.x * scale;
      const ey = cy + e.pos.z * scale;
      const rel = e.level - hero.level;
      let color = '#87e59a';
      if (rel >= 3) color = '#ff5b4e';
      else if (rel >= 1) color = '#ffd166';
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(ex, ey, rel >= 3 ? 3.4 : 2.6, 0, Math.PI * 2);
      ctx.fill();
      if (e.isCaster) {
        ctx.strokeStyle = 'rgba(176,123,255,0.8)';
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.arc(ex, ey, 5.2, 0, Math.PI * 2);
        ctx.stroke();
      }
    }

    // player
    const px = cx + hero.position.x * scale;
    const py = cy + hero.position.z * scale;
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(Math.PI - hero.yawAngle);
    ctx.fillStyle = '#fff8e4';
    ctx.strokeStyle = 'rgba(0,0,0,0.55)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(0, -8);
    ctx.lineTo(5.5, 6);
    ctx.lineTo(0, 3);
    ctx.lineTo(-5.5, 6);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();

    // sweep
    const sweep = (performance.now() * 0.0005) % (Math.PI * 2);
    const sg = ctx.createLinearGradient(cx, cy, cx + Math.cos(sweep) * w / 2, cy + Math.sin(sweep) * w / 2);
    sg.addColorStop(0, 'rgba(139,224,164,0.16)');
    sg.addColorStop(1, 'rgba(139,224,164,0)');
    ctx.strokeStyle = sg;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(sweep) * w / 2, cy + Math.sin(sweep) * w / 2);
    ctx.stroke();

    ctx.restore();
    ctx.strokeStyle = 'rgba(139,224,164,0.35)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(cx, cy, w / 2 - 2, 0, Math.PI * 2);
    ctx.stroke();
  }

  spawnNumber(pos, text, cls = '', offset = null) {
    if (this.damage.length > 34) {
      const old = this.damage.shift();
      old.el.remove();
    }
    const el = document.createElement('span');
    el.className = `dmg ${cls}`;
    el.textContent = text;
    this.el.damageLayer.appendChild(el);
    this.damage.push({
      el,
      pos: pos.clone(),
      life: cls === 'crit' ? 1.05 : 0.82,
      max: cls === 'crit' ? 1.05 : 0.82,
      dx: offset?.x ?? (Math.random() * 34 - 17),
      rise: 38 + Math.random() * 18
    });
  }

  updateDamage(camera, dt) {
    const w = window.innerWidth;
    const h = window.innerHeight;
    for (let i = this.damage.length - 1; i >= 0; i--) {
      const d = this.damage[i];
      d.life -= dt;
      if (d.life <= 0) {
        d.el.remove();
        this.damage.splice(i, 1);
        continue;
      }
      const p = d.pos.clone();
      p.project(camera);
      if (p.z > 1 || p.z < -1) { d.el.style.opacity = '0'; continue; }
      const x = (p.x * 0.5 + 0.5) * w + d.dx;
      const y = (-p.y * 0.5 + 0.5) * h;
      const t = 1 - d.life / d.max;
      const scale = 0.75 + Math.min(1, t * 7) * 0.35;
      d.el.style.transform = `translate3d(${x}px, ${y - t * d.rise}px, 0) translate(-50%, -50%) scale(${scale})`;
      d.el.style.opacity = String(Math.min(1, d.life / d.max * 2.2));
    }
  }

  toast(text, type = '', duration = 2300) {
    const el = document.createElement('div');
    el.className = `toast ${type}`;
    el.textContent = text;
    this.el.toastLayer.appendChild(el);
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 500);
    }, duration);
  }

  hitFlash() {
    const el = this.el.flash;
    el.style.transition = 'none';
    el.style.opacity = '0.85';
    requestAnimationFrame(() => {
      el.style.transition = 'opacity 520ms ease-out';
      el.style.opacity = '0';
    });
  }

  shakeHud() {
    this.el.hud.animate(
      [{ transform: 'translate(0,0)' }, { transform: 'translate(4px,-3px)' }, { transform: 'translate(-3px,2px)' }, { transform: 'translate(0,0)' }],
      { duration: 160, easing: 'ease-out' }
    );
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = localStorage.getItem('skullfall.muted') === '1';
    this.noiseBuffer = null;
    this.wind = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.7;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoise(2.5);
    this.startWind();
  }

  makeNoise(seconds) {
    const length = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.96 + white * 0.04;
      data[i] = last * 3.2;
    }
    return buffer;
  }

  startWind() {
    if (!this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 360;
    const gain = this.ctx.createGain();
    gain.gain.value = 0.055;
    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.09;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 0.025;
    lfo.connect(lfoGain);
    lfoGain.connect(gain.gain);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    src.start();
    lfo.start();
    this.wind = { src, gain };
  }

  setMuted(muted) {
    this.muted = muted;
    localStorage.setItem('skullfall.muted', muted ? '1' : '0');
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.7, this.ctx.currentTime, 0.05);
  }

  tone(freq, endFreq, dur, type = 'sine', gain = 0.15, delay = 0) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + Math.min(0.02, dur * 0.2));
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  noise(dur, gain, type = 'bandpass', f0 = 1200, f1 = 400, delay = 0, q = 1) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.Q.value = q;
    filter.frequency.setValueAtTime(f0, t);
    filter.frequency.exponentialRampToValueAtTime(Math.max(40, f1), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.05);
  }

  click() {
    this.tone(460, 320, 0.08, 'triangle', 0.12);
    this.noise(0.06, 0.05, 'highpass', 2000, 1000);
  }

  swing(step = 0) {
    const base = 1300 + step * 250;
    this.noise(0.22, 0.16, 'bandpass', base, 380, 0, 1.6);
    this.tone(280 - step * 30, 140, 0.14, 'triangle', 0.075);
  }

  hit(crit = false) {
    this.tone(crit ? 180 : 140, 52, crit ? 0.2 : 0.12, 'sine', crit ? 0.3 : 0.2);
    this.noise(crit ? 0.16 : 0.1, crit ? 0.22 : 0.15, 'lowpass', 1700, 300, 0, 0.8);
    if (crit) {
      this.tone(880, 660, 0.18, 'triangle', 0.1, 0.01);
      this.noise(0.14, 0.1, 'highpass', 2600, 900, 0.01);
    }
  }

  enemyDie(big = false) {
    this.tone(big ? 220 : 260, 54, 0.42, 'triangle', big ? 0.22 : 0.14);
    this.noise(0.35, 0.12, 'lowpass', 1300, 180);
    this.tone(big ? 90 : 120, 40, 0.5, 'sawtooth', 0.05, 0.02);
    for (let i = 0; i < 3; i++) {
      this.tone(700 + i * 180, 500 + i * 120, 0.09, 'square', 0.025, 0.06 + i * 0.045);
    }
  }

  hurt() {
    this.tone(190, 70, 0.24, 'sawtooth', 0.16);
    this.noise(0.2, 0.14, 'lowpass', 900, 180);
  }

  levelUp() {
    const notes = [523, 659, 784, 1046];
    notes.forEach((n, i) => {
      this.tone(n, n * 1.005, 0.5, 'triangle', 0.12, i * 0.095);
      this.tone(n / 2, n / 2, 0.55, 'sine', 0.06, i * 0.095);
    });
    this.noise(0.6, 0.045, 'highpass', 5000, 2000, 0.1);
  }

  death() {
    this.tone(180, 42, 1.1, 'sawtooth', 0.16);
    this.tone(128, 32, 1.4, 'sine', 0.18, 0.1);
    this.noise(1.2, 0.1, 'lowpass', 900, 100, 0.05);
  }

  respawn() {
    const notes = [392, 523, 659, 784];
    notes.forEach((n, i) => this.tone(n, n, 0.35, 'sine', 0.09, i * 0.08));
    this.noise(0.7, 0.06, 'highpass', 1200, 3000, 0.1);
  }

  skill() {
    this.noise(0.5, 0.2, 'bandpass', 500, 3200, 0, 2.2);
    this.tone(220, 880, 0.4, 'triangle', 0.1);
    this.tone(330, 1320, 0.45, 'sine', 0.07, 0.04);
    this.noise(0.4, 0.12, 'highpass', 4000, 1200, 0.16);
  }

  cast() {
    this.tone(280, 760, 0.3, 'sine', 0.06);
    this.noise(0.26, 0.05, 'bandpass', 900, 2400, 0, 2.5);
  }

  impact() {
    this.tone(120, 46, 0.18, 'sine', 0.16);
    this.noise(0.22, 0.13, 'lowpass', 1600, 240);
  }

  noMana() {
    this.tone(180, 120, 0.09, 'square', 0.06);
    this.tone(150, 100, 0.12, 'square', 0.05, 0.09);
  }

  zone() {
    this.tone(330, 440, 0.4, 'sine', 0.05);
    this.tone(495, 660, 0.5, 'sine', 0.04, 0.08);
  }

  deny() {
    this.tone(140, 100, 0.1, 'square', 0.05);
  }
