  enemies.onHit = (enemy, dmg, crit) => {
    game.combo += 1;
    game.comboTimer = 2.8;
    ui.spawnNumber(
      new THREE.Vector3(enemy.group.position.x, enemy.group.position.y + 0.4, enemy.group.position.z),
      String(dmg),
